import sys
import time
import urllib.error
import urllib.parse
import urllib.request

import config


def _page_url(dataset_id, columns, offset):
    params = {"$limit": config.PAGE_SIZE, "$offset": offset, "$order": ":id"}
    if columns:
        params["$select"] = ",".join(columns)
    return f"{config.SOCRATA_BASE}/{dataset_id}.csv?{urllib.parse.urlencode(params)}"


def _fetch(url, tries=4):
    """Return the response body as text, retrying on temporary failures."""
    for attempt in range(1, tries + 1):
        try:
            with urllib.request.urlopen(url, timeout=120) as resp:
                return resp.read().decode("utf-8")
        except urllib.error.HTTPError as err:
            if err.code == 400:
                raise  # bad column name: the caller handles it
            if attempt == tries:
                raise
        except urllib.error.URLError:
            if attempt == tries:
                raise
        time.sleep(5 * attempt)


def download(name):
    spec = config.DATASETS[name]
    out_path = config.RAW_DIR / f"{name}.csv"
    config.RAW_DIR.mkdir(parents=True, exist_ok=True)

    columns = (spec["select"] or []) + spec["optional"] if spec["select"] else None
    offset, rows = 0, 0
    with open(out_path, "w", encoding="utf-8", newline="") as out:
        while True:
            try:
                text = _fetch(_page_url(spec["id"], columns, offset))
            except urllib.error.HTTPError as err:
                if err.code == 400 and offset == 0 and columns:
                    detail = err.read().decode("utf-8", "replace")[:400]
                    print(f"  The server rejected a column name for '{name}':\n  {detail}")
                    if spec["optional"] and columns != spec["select"]:
                        print("  Retrying without the optional columns.")
                        columns = spec["select"]
                        continue
                    print("  Fix DATASETS in config.py, or set its 'select' to None "
                          "to download every column.")
                raise
            lines = text.splitlines(keepends=True)
            if len(lines) <= 1:          # header only: no more rows
                if offset == 0:
                    out.writelines(lines)
                break
            out.writelines(lines if offset == 0 else lines[1:])
            got = len(lines) - 1
            rows += got
            print(f"  {name}: about {rows:,} rows so far")
            # A short page means the end, but only if no field contains line breaks,
            # so keep going until a page comes back empty.
            offset += config.PAGE_SIZE
    print(f"Saved {out_path}")


def main(argv):
    names = argv or list(config.DATASETS)
    for name in names:
        if name not in config.DATASETS:
            sys.exit(f"Unknown dataset '{name}'. Choose from: {', '.join(config.DATASETS)}")
        print(f"Downloading {name} ...")
        download(name)


if __name__ == "__main__":
    main(sys.argv[1:])
